const clickPreview = async (idx) => {
  await tools.browser.evaluate({
    tabID,
    script: `(() => { const b=[...document.querySelectorAll('.preview-tab')]; b[${idx}].click(); return b[${idx}].getAttribute('aria-selected') })()`
  })
  return (await tools.browser.evaluate({ tabID, script: `document.getAnimations().filter(a => a.transitionProperty).map(a => ({p:a.transitionProperty, s:a.playState, ct:a.currentTime}))` })).value
}
const a = await clickPreview(1)
const b = await clickPreview(2)
const c = await clickPreview(1)
const d = await clickPreview(0)
return { a, b, c, d }

